const base = $('Normalize Payload').first().json;
const incoming = $input.first()?.json || {};

const sanitizarPII = (texto) => {
  let t = String(texto || '');
  t = t.replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[CORREO]');
  t = t.replace(/(?:\+?57[\s-]?)?3\d{2}[\s-]?\d{3}[\s-]?\d{4}/g, '[TELEFONO]');
  t = t.replace(/\b(?:cc|c\.c\.|ti|nit|tel|cel|celular|telefono|teléfono|whatsapp)\s*[:#.-]?\s*\d{6,12}\b/gi, '[DATO_CONTACTO]');
  t = t.replace(/\b\d{6,12}\b/g, '[NUMERO]');
  t = t.replace(/\b(?:calle|cll|carrera|cra|kr|avenida|av|diagonal|diag|transversal|transv|tv|manzana|mz|casa|apto|apartamento|torre)\s*#?\s*\d+[a-zA-Z]?(?:\s*(?:#|no\.?|n°|-)\s*\d+[a-zA-Z]?(?:\s*-\s*\d+)?)?/gi, '[DIRECCION]');
  return t.replace(/\s+/g, ' ').trim().slice(0, 1500);
};

let visionText = '';
let visionModel = '';
let visionError = false;

if (incoming.error) {
  visionError = true;
  visionText = 'No fue posible analizar las fotografias con IA visual.';
} else if (typeof incoming.visionSummary === 'string' && incoming.visionSummary.trim()) {
  visionText = sanitizarPII(incoming.visionSummary);
} else if (typeof incoming.content === 'string' && incoming.content.trim()) {
  visionText = sanitizarPII(incoming.content);
  visionModel = 'models/gemini-3.5-flash-lite';
} else if (typeof incoming.text === 'string' && incoming.text.trim()) {
  visionText = sanitizarPII(incoming.text);
  visionModel = 'models/gemini-3.5-flash-lite';
} else if (Array.isArray(incoming.content?.parts)) {
  visionText = sanitizarPII(incoming.content.parts.map((p) => p?.text || '').filter(Boolean).join(' '));
  visionModel = 'models/gemini-3.5-flash-lite';
} else {
  visionText = base.total_fotos > 0 ? 'Analisis visual sin observaciones textuales.' : 'Sin fotografias adjuntas en la denuncia.';
}

return [{
  json: {
    ...base,
    descripcion_ia: sanitizarPII(base.descripcion),
    visionSummary: visionText,
    visionModel,
    visionError
  }
}];

const norm = $('Normalize Payload').first().json;
const visionCtx = $('Prepare Vision Context').first().json;

let iaRaw = {};
let iaError = false;
try {
  iaRaw = $('Analyze Text Triage').first().json || {};
  if (iaRaw.error) iaError = true;
} catch (e) {
  iaError = true;
}

let dupRaw = {};
try {
  dupRaw = $('Detect Duplicates').first().json || {};
} catch (e) {
  dupRaw = {};
}

let cargaRaw = {};
try {
  cargaRaw = $('Fetch Vet Workload').first().json || {};
} catch (e) {
  cargaRaw = {};
}

let parsedIa = {};
const candidateText =
  typeof iaRaw.content === 'string'
    ? iaRaw.content
    : (typeof iaRaw.text === 'string'
        ? iaRaw.text
        : (Array.isArray(iaRaw.content?.parts)
            ? iaRaw.content.parts.map((p) => p?.text || '').join('')
            : (typeof iaRaw === 'object' && iaRaw.prioridad_sugerida ? JSON.stringify(iaRaw) : '')));

if (!iaError && candidateText) {
  try {
    const cleaned = candidateText.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
    const obj = JSON.parse(cleaned);
    if (!obj || typeof obj !== 'object' || Array.isArray(obj)) {
      iaError = true;
    } else {
      parsedIa = obj;
    }
  } catch (e) {
    iaError = true;
  }
} else {
  iaError = true;
}

const PRIORIDADES_PERMITIDAS = new Set(['URGENTE', 'ALTA', 'MEDIA', 'BAJA']);
const rawPrio = String(parsedIa.prioridad_sugerida || '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim()
  .toUpperCase();
const mapPrioridad = (val) => {
  if (PRIORIDADES_PERMITIDAS.has(val)) return val;
  if (val === 'CRITICA' || val === 'EMERGENCIA') return 'URGENTE';
  if (val === 'NORMAL') return 'MEDIA';
  return null;
};

const limpiarListaStrings = (arr, maxItems = 15, maxLen = 100) => {
  if (!Array.isArray(arr)) return [];
  const vistos = new Set();
  const res = [];
  for (const item of arr) {
    if (typeof item !== 'string') continue;
    const limpio = item.replace(/\s+/g, ' ').trim().slice(0, maxLen);
    if (!limpio) continue;
    const key = limpio.toLowerCase();
    if (vistos.has(key)) continue;
    vistos.add(key);
    res.push(limpio);
    if (res.length >= maxItems) break;
  }
  return res;
};

const prioridadSugerida = !iaError ? mapPrioridad(rawPrio) : null;
let confianzaValida = null;
if (!iaError && typeof parsedIa.nivel_confianza === 'number' && Number.isFinite(parsedIa.nivel_confianza)) {
  confianzaValida = Math.max(0, Math.min(1, Math.round(parsedIa.nivel_confianza * 10000) / 10000));
}

const tieneFotosReales = Number(norm.total_fotos || 0) > 0 && !visionCtx.visionError;
const signosReportados = !iaError ? limpiarListaStrings(parsedIa.signos_reportados, 15, 100) : [];
const signosFotografia = (!iaError && tieneFotosReales)
  ? limpiarListaStrings(parsedIa.signos_fotografia, 15, 100)
  : [];

let signosValidados = !iaError ? limpiarListaStrings(parsedIa.signos_detectados, 15, 100) : [];
if (signosValidados.length === 0) {
  signosValidados = limpiarListaStrings([...signosReportados, ...signosFotografia], 15, 100);
}

let advertenciasContradiccion = (!iaError && tieneFotosReales)
  ? limpiarListaStrings(parsedIa.advertencias_contradiccion, 5, 400)
  : [];
const contradiccionFotoDescripcion = Boolean(
  !iaError &&
  tieneFotosReales &&
  (parsedIa.contradiccion_foto_descripcion === true || advertenciasContradiccion.length > 0)
);
if (contradiccionFotoDescripcion && advertenciasContradiccion.length === 0) {
  advertenciasContradiccion = [
    'La evidencia fotografica presenta diferencias relevantes frente a la descripcion reportada por el ciudadano; revise ambas antes de decidir.'
  ];
}
if (!contradiccionFotoDescripcion) {
  advertenciasContradiccion = [];
}

const schemaInvalido = !iaError && (!prioridadSugerida || typeof parsedIa.justificacion !== 'string' || !parsedIa.justificacion.trim());
const posiblesDuplicados = Array.isArray(dupRaw.posibles_duplicados) ? dupRaw.posibles_duplicados : [];
const vetRec = cargaRaw.veterinario_recomendado || null;
const cargaLista = Array.isArray(cargaRaw.veterinarios) ? cargaRaw.veterinarios : [];

const estadoAnalisis = (iaError || schemaInvalido || visionCtx.visionError || !prioridadSugerida)
  ? ((dupRaw && !dupRaw.error) || (cargaRaw && !cargaRaw.error) ? 'PARCIAL' : 'FALLIDO')
  : 'COMPLETADO';

return [{
  json: {
    id_peticion: norm.id_peticion,
    backendBaseUrl: norm.backendBaseUrl,
    clave_idempotencia: norm.clave_idempotencia,
    despacho_token: norm.despacho_token || '',
    estado_analisis: estadoAnalisis,
    prioridad_sugerida: prioridadSugerida,
    nivel_confianza: confianzaValida,
    justificacion: (typeof parsedIa.justificacion === 'string' && parsedIa.justificacion.trim())
      ? parsedIa.justificacion.trim().slice(0, 3000)
      : (iaError || schemaInvalido ? 'Analisis de IA no disponible o respuesta invalida; se recopilaron duplicados y carga laboral.' : ''),
    resumen_texto: typeof parsedIa.resumen_texto === 'string' ? parsedIa.resumen_texto.trim().slice(0, 2000) : '',
    resumen_vision: typeof parsedIa.resumen_vision === 'string' && parsedIa.resumen_vision.trim()
      ? parsedIa.resumen_vision.trim().slice(0, 2000)
      : (visionCtx.visionSummary || '').slice(0, 2000),
    signos_detectados: signosValidados,
    signos_reportados: signosReportados,
    signos_fotografia: signosFotografia,
    contradiccion_foto_descripcion: contradiccionFotoDescripcion,
    advertencias_contradiccion: advertenciasContradiccion,
    posibles_duplicados: posiblesDuplicados,
    veterinario_recomendado_id: vetRec ? vetRec.id_veterinario : null,
    justificacion_recomendacion: cargaRaw.justificacion_recomendacion || '',
    carga_veterinarios_snapshot: cargaLista,
    modelo_texto_usado: (iaError || schemaInvalido) ? '' : 'models/gemini-3.5-flash-lite',
    modelo_vision_usado: visionCtx.visionModel || '',
    n8n_execution_id: String($execution.id || ''),
    resultado_raw: {
      ia: parsedIa,
      schema_invalido: schemaInvalido,
      duplicados_meta: dupRaw.parametros || {}
    }
  }
}];
